#!/usr/bin/env python3
"""Check numerical E(T) table generated by C++ against signed-off Stage3D00-v4 material values."""
from pathlib import Path
import csv, math
root=Path(__file__).resolve().parents[1]
ref=root/'reference/E_T_REFERENCE_VALUES_v4.csv'
calc=root/'build/material/MAT_T01_T02_T03.csv'
with ref.open(encoding='utf-8-sig',newline='') as f:rows=list(csv.DictReader(f))
with calc.open(encoding='utf-8-sig',newline='') as f:table={float(row['T_C']):row for row in csv.DictReader(f)}
worst=0.
for row in rows:
 t=float(row['T_C']);assert t in table,(t,'Missing C++ reference temperature')
 computed=float(table[t]['E_VAR_Pa'])/1e6
 expected=float(row['E_var_MPa'])
 err=abs(computed-expected)
 worst=max(worst,err)
 if err>1e-5:raise RuntimeError(f'MAT-T03 reference mismatch at {t}: {computed} vs {expected}')
assert len(rows)==12
print(f'PASS MAT-T03: {len(rows)} v4 reference rows, max |E_VAR mismatch|={worst:.9g} MPa')
